fn smallest_change(arr: Vec<i8>) -> usize {
    let n = arr.len();
    let mut mismatches = 0;
    for i in 0..(n / 2) {
        if arr[i] != arr[n - 1 - i] {
            mismatches += 1;
        }
    }
    mismatches
}

